-- Databases for apps: an app can have one Postgres of its own, run by the
-- platform as a container next to it (see docs/decisions/platform.md). A row
-- here is the desired state; the reconciler creates the container, its
-- volume and its network, and keeps it running.
CREATE TABLE app_databases (
    -- One per app. Deleting an app deletes the row (its volume, which holds
    -- the data, is never removed by the platform).
    app_id bigint PRIMARY KEY REFERENCES apps (id) ON DELETE CASCADE,
    -- The database user's password, generated by the platform, encrypted
    -- like env vars (AES-256-GCM, bound to this row). Apps get it inside
    -- DATABASE_URL; it's never shown.
    encrypted_password bytea NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    -- When the reconciler first created its container (NULL until then).
    -- Tells "not created yet" from "its container was deleted", which
    -- Docker can't say without the volumes permission the platform doesn't
    -- have; and lets the dashboard show it's still being created.
    provisioned_at timestamptz
);

-- The reconciler records creating a database as an event of its own.
ALTER TABLE reconciler_events DROP CONSTRAINT reconciler_events_kind_check;
ALTER TABLE reconciler_events ADD CONSTRAINT reconciler_events_kind_check CHECK (kind IN (
    'restarted', 'recreated', 'crash_looping', 'removed_orphan',
    'routes_reapplied', 'fix_failed',
    'database_created' -- an app's database container created for the first time
));
